fn load_mask_program(path:&str)->MaskProgram{let data=std::fs::read(path).unwrap();assert_eq!(&data[..8],b"MRMASK01");let read64=|off|u64::from_le_bytes(data[off..off+8].try_into().unwrap())as usize;let n=read64(8);let inputs=read64(16);let outputs=read64(24);assert!(n>=2&&n<100000000);assert_eq!(inputs,1024);assert_eq!(outputs,512);assert_eq!(data.len(),32+n*16+outputs*4);let read32=|off|u32::from_le_bytes(data[off..off+4].try_into().unwrap());let mut nodes=Vec::with_capacity(n);for i in 0..n{let off=32+i*16;let node=MaskNode{kind:read32(off),a:read32(off+4),b:read32(off+8),aux:read32(off+12)};assert_eq!(node.aux,0);match node.kind{0|1=>{},2=>assert!((node.a as usize)<inputs),3|4|5=>assert!((node.a as usize)<i&&(node.b as usize)<i),_=>panic!("unknown mask terminal")};nodes.push(node);}let roots=(0..outputs).map(|i|{let r=read32(32+n*16+i*4);assert!((r as usize)<n);r}).collect();MaskProgram{nodes,roots,inputs,old_live:0}}
struct ZeroReader;impl XofReader for ZeroReader{fn read(&mut self,out:&mut[u8]){out.fill(0);}}
fn validation_random(seed:u64)->sha3::Shake256Reader{let mut h=Shake256::default();h.update(b"mr-mask-independent-protected-v1");h.update(&seed.to_le_bytes());h.finalize_xof()}
fn main(){let args:Vec<_>=std::env::args().collect();let ops=load_ops(&args[1]).unwrap();let program=load_mask_program(&args[2]);let(nq,nb,_,regs)=analyze_ops(ops.iter());assert_eq!(regs.len(),4);assert!(regs.iter().all(|r|r.len()==256));let rows:Vec<Vec<U256>>=std::fs::read_to_string(&args[3]).unwrap().lines().filter(|l|!l.trim().is_empty()).map(|l|l.split_whitespace().skip(1).map(|v|U256::from_str_radix(v.trim_start_matches("0x"),16).unwrap()).collect()).collect();assert!(rows.iter().all(|r|r.len()==6));let placeholder=args[3].contains("sensitivity-arbitrary");let timer=std::time::Instant::now();let(mut batches,mut knownbits,mut certified_wrong,mut mask_seconds)=(0,0usize,0usize,0f64);for data in rows.chunks(64){let mut zero_reader=ZeroReader;let mut zero=Simulator::new(nq as usize,nb as usize,&mut zero_reader);let mut expected=vec![0u64;512];for(lane,row)in data.iter().enumerate(){for(reg,value)in regs[..4].iter().zip(&row[..4]){zero.set_register(reg,*value,lane);}for reg in 0..2{for bit in 0..256{expected[reg*256+bit]|=(row[4+reg].bit(bit)as u64)<<lane;}}}let initialq=zero.qubits.clone();let initialb=zero.bits.clone();let input:Vec<u64>=regs.iter().flatten().map(|w|match w{QubitOrBit::Qubit(id)=>initialq[id.0 as usize],QubitOrBit::Bit(id)=>initialb[id.0 as usize]}).collect();let start=std::time::Instant::now();let known=program.eval(&input);mask_seconds+=start.elapsed().as_secs_f64();let active=if data.len()==64{u64::MAX}else{(1u64<<data.len())-1};knownbits+=known.iter().map(|m|(m&active).count_ones()as usize).sum::<usize>();zero.apply_iter(ops.iter());let mut wrong=0u64;for(index,w)in regs[..2].iter().flatten().enumerate(){let actual=match w{QubitOrBit::Qubit(id)=>zero.qubits[id.0 as usize],QubitOrBit::Bit(id)=>zero.bits[id.0 as usize]};wrong|=(actual^expected[index])&known[index]&active;}if !placeholder{certified_wrong+=wrong.count_ones()as usize;}for seed in 0..8{let mut random=validation_random(seed);let mut sim=Simulator::new(nq as usize,nb as usize,&mut random);sim.qubits.copy_from_slice(&initialq);sim.bits.copy_from_slice(&initialb);sim.apply_iter(ops.iter());for(index,w)in regs[..2].iter().flatten().enumerate(){let(z,v)=match w{QubitOrBit::Qubit(id)=>(zero.qubits[id.0 as usize],sim.qubits[id.0 as usize]),QubitOrBit::Bit(id)=>(zero.bits[id.0 as usize],sim.bits[id.0 as usize])};assert_eq!((v^z)&known[index]&active,0,"protected MR mask containment bit{index} batch{batches} seed{seed}");}if !placeholder{for lane in 0..data.len(){if wrong>>lane&1!=0{assert!(sim.get_register(&regs[0],lane)!=data[lane][4]||sim.get_register(&regs[1],lane)!=data[lane][5]);}}}}batches+=1;}
println!("{}",serde_json::json!({"source_stream":args[1],"mask_program":args[2],"fixture":args[3],"program_nodes":program.nodes.len(),"input_count":program.inputs,"output_count":program.roots.len(),"shots":rows.len(),"batches":batches,"independent_physical_mr_streams":8,"known_scored_bits":knownbits,"certified_wrong_value_shots":if placeholder{serde_json::Value::Null}else{serde_json::json!(certified_wrong)},"placeholder_expected_values_not_used_for_failure_claim":placeholder,"mask_seconds":mask_seconds,"mask_us_per_shot":mask_seconds*1e6/rows.len()as f64,"protected_known_bit_containment_passed":true,"seconds":timer.elapsed().as_secs_f64(),"status":"INPUT_CONDITIONED_MR_MASK_PROTECTED_VALIDATION_NOT_GLOBAL_INDEPENDENCE"}));}
